select

from filing_customer_info a
left join filing_customer_transfer b on a.id = b.filing_id and b.move_status = '0'
left join sys_user u on a.filing_manager_code = u.manager_num

    ${params.dataScope}
    and a.id in

            #{id}



        and a.id in (SELECT customer_id FROM custom_group_customer where custom_group_id in

            #{customGroupId}

        )

    and a.customer_type = #{customerType }
    and a.customer_name like concat('%', #{customerName},
        '%')

    and a.customer_address = #{customerAddress }

    and a.customer_phone like concat('%',
        #{customerPhone}, '%')

    and a.customer_identity = #{customerIdentity}

    and a.customer_source = #{customerSource }
    and a.belong_grid_code = #{belongGridCode }
    and a.belong_grid_name = #{belongGridName }
    and a.filing_manager_code =
        #{filingManagerCode }

    and a.filing_manager_name =
        #{filingManagerName }

    and a.filing_org_code = #{filingOrgCode }
    and a.filing_org_name = #{filingOrgName }
    and a.filing_progress = #{filingProgress }
    and a.filing_source = #{filingSource }
    and a.filing_status = #{filingStatus }

    and a.filing_status != '0'
    and a.filing_date = #{filingDate }
    and a.create_time = #{createTime }
    and a.update_time = #{updateTime }
    and
        a.customer_introducer_identity like concat('%', #{customerIntroducerIdentity}, '%')

    and a.customer_address_type =
        #{customerAddressType}

    and a.customer_nm like concat('%', #{customerNm}, '%')

    and a.model_id = #{modelId}
    and a.clock_in = #{clockIn}
    and a.customer_photo = #{customerPhoto}
    and belong_grid_code in

            #{belongGridCode}



        and filing_org_code in

            #{item}


    and (a.customer_name like concat('%', #{query}, '%')
        or a.customer_identity like concat('%', #{query}, '%')
        or a.customer_phone like concat('%', #{query}, '%'))


order by a.create_time desc

